// types.cpp - Four kinds of user-defined functions
#include <iostream>
using namespace std;

void line() {                         // no argument, no return
    cout << "--------------------" << endl;
}

void showSum(int a, int b) {          // argument, no return
    cout << "Sum = " << a + b << endl;
}

int readNumber() {                    // no argument, return value
    int n;
    cout << "Enter a number: ";
    cin >> n;
    return n;
}

int maximum(int a, int b) {           // argument and return value
    return (a > b) ? a : b;
}

int main() {
    line();
    int p = readNumber();
    int q = readNumber();
    showSum(p, q);
    cout << "Maximum = " << maximum(p, q) << endl;
    line();
    return 0;
}

// prime_func.cpp - Using a function to list primes
#include <iostream>
using namespace std;

bool isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; i++)
        if (n % i == 0) return false;
    return true;
}

int main() {
    int a, b;
    cout << "Enter range (start end): ";
    cin >> a >> b;
    cout << "Primes: ";
    for (int i = a; i <= b; i++)
        if (isPrime(i)) cout << i << " ";
    cout << endl;
    return 0;
}

// swapref.cpp - Call by value vs call by reference
#include <iostream>
using namespace std;

void swapValue(int a, int b) {        // copies are swapped
    int t = a; a = b; b = t;
}

void swapRef(int &a, int &b) {        // originals are swapped
    int t = a; a = b; b = t;
}

int main() {
    int x = 10, y = 20;

    swapValue(x, y);
    cout << "After call by value     : x = " << x << ", y = " << y << endl;

    swapRef(x, y);
    cout << "After call by reference : x = " << x << ", y = " << y << endl;
    return 0;
}

// defaultarg.cpp - Default arguments
#include <iostream>
using namespace std;

float simpleInterest(float p, float r = 7.5, int t = 1) {
    return p * r * t / 100;
}

int main() {
    cout << simpleInterest(10000) << endl;          // r = 7.5, t = 1
    cout << simpleInterest(10000, 8) << endl;       // t = 1
    cout << simpleInterest(10000, 8, 3) << endl;    // all given
    return 0;
}

// overload.cpp - Function overloading
#include <iostream>
using namespace std;

int area(int side) {                   // square
    return side * side;
}

int area(int length, int breadth) {    // rectangle
    return length * breadth;
}

double area(double radius) {           // circle
    return 3.14159 * radius * radius;
}

int main() {
    cout << "Square    : " << area(5) << endl;
    cout << "Rectangle : " << area(4, 6) << endl;
    cout << "Circle    : " << area(2.0) << endl;
    return 0;
}

// scope.cpp - Local and global variables
#include <iostream>
using namespace std;

int score = 100;          // global variable

void show() {
    int score = 5;        // local variable hides the global one
    cout << "Local score  = " << score << endl;
    cout << "Global score = " << ::score << endl;   // scope resolution
}

int main() {
    show();
    score = score + 1;    // changes the global variable
    cout << "Global score in main = " << score << endl;
    return 0;
}

