// dice.cpp - Random numbers with <cstdlib> and <ctime>
#include <iostream>
#include <cstdlib>
#include <ctime>
using namespace std;

int rollDice() {
    return rand() % 6 + 1;          // 1 to 6
}

int main() {
    srand(time(0));                 // new random sequence each run
    cout << "Rolling the dice 5 times: ";
    for (int i = 1; i <= 5; i++)
        cout << rollDice() << " ";
    cout << endl;
    return 0;
}

// recursion.cpp - Factorial using recursion
#include <iostream>
using namespace std;

long long factorial(int n) {
    if (n <= 1)                     // base case
        return 1;
    return n * factorial(n - 1);    // recursive call
}

int main() {
    for (int i = 1; i <= 6; i++)
        cout << i << "! = " << factorial(i) << endl;
    return 0;
}

