#include <iostream>
using namespace std;

int maxOf(int a, int b)           { return (a > b) ? a : b; }
int maxOf(int a, int b, int c)    { return maxOf(maxOf(a, b), c); }
double maxOf(double a, double b)  { return (a > b) ? a : b; }

int main() {
    cout << maxOf(4, 9) << endl;        // 9
    cout << maxOf(4, 9, 7) << endl;     // 9
    cout << maxOf(2.5, 1.5) << endl;    // 2.5
    return 0;
}

#include <iostream>
using namespace std;

bool isArmstrong(int n) {
    int temp = n, sum = 0;
    while (temp > 0) {
        int d = temp % 10;
        sum += d * d * d;
        temp /= 10;
    }
    return sum == n;
}

int main() {
    for (int i = 100; i <= 999; i++)
        if (isArmstrong(i)) cout << i << " ";
    return 0;
}

#include <iostream>
using namespace std;

long long factorial(int n) {
    long long f = 1;
    for (int i = 2; i <= n; i++) f *= i;
    return f;
}

bool isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; i++)
        if (n % i == 0) return false;
    return true;
}

int reverseNum(int n) {
    int r = 0;
    while (n > 0) { r = r * 10 + n % 10; n /= 10; }
    return r;
}

int main() {
    int choice, n;
    do {
        cout << "\n1. Factorial\n2. Prime check\n3. Reverse\n4. Exit\nChoice: ";
        cin >> choice;
        if (choice >= 1 && choice <= 3) {
            cout << "Enter number: ";
            cin >> n;
        }
        switch (choice) {
            case 1: cout << "Factorial = " << factorial(n) << endl; break;
            case 2: cout << (isPrime(n) ? "Prime" : "Not prime") << endl;
break;
            case 3: cout << "Reverse = " << reverseNum(n) << endl; break;
            case 4: cout << "Bye!" << endl; break;
            default: cout << "Invalid choice" << endl;
        }
    } while (choice != 4);
    return 0;
}

int fib(int n) {
    if (n == 0) return 0;        // base cases
    if (n == 1) return 1;
    return fib(n - 1) + fib(n - 2);
}
